async def act(page):
    """
    From the current New Product form state, finish configuring the product and Save:
      - Ensure Status = Enabled
      - Set Price = 69.99
      - Open Inventory and set Qty = 50 and Stock Availability = In Stock
      - Set Size = 38 and Color = Yellow if those attribute controls are present

    Final action: click Save (navigation-causing). No selectors after Save.

    Knowledge-base functions: none are available, so none are used.
    """
    # ensure the page is settled
    await page.wait_for_load_state("networkidle")

    # 1) Set Status -> Enabled using the explicit table -> rowgroup -> row path
    try:
        status_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name=lambda n: n and "status" in n.lower()
        )
        if await status_row.count() > 0:
            status_cb = status_row.get_by_role("combobox", name=lambda n: n and "status" in n.lower())
            if await status_cb.count() > 0:
                await status_cb.select_option("Enabled")
    except Exception:
        # best-effort fallback: any combobox whose name contains 'status'
        try:
            fallback_status = page.get_by_role("combobox", name=lambda n: n and "status" in n.lower())
            if await fallback_status.count() > 0:
                await fallback_status.select_option("Enabled")
        except Exception:
            pass

    # 2) Click the Prices link to reveal the price field, then set Price = 69.99
    try:
        # scope link under document per guidance
        prices_link = page.get_by_role("document").get_by_role("link", name="Prices")
        if await prices_link.count() > 0:
            await prices_link.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        # ignore if not present
        pass

    # Try to fill price by an explicit row if present, else any textbox with 'price' in name
    try:
        price_row = page.get_by_role("table").get_by_role("rowgroup").get_by_role(
            "row", name=lambda n: n and "price" in n.lower()
        )
        if await price_row.count() > 0:
            price_tb = price_row.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await price_tb.count() > 0:
                await price_tb.fill("69.99")
        else:
            # fallback
            any_price = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await any_price.count() > 0:
                await any_price.fill("69.99")
    except Exception:
        try:
            any_price = page.get_by_role("textbox", name=lambda n: n and "price" in n.lower())
            if await any_price.count() > 0:
                await any_price.fill("69.99")
        except Exception:
            pass

    # 3) Click Inventory link/tab to expose inventory controls and set Qty and Stock Availability
    try:
        inv_link = page.get_by_role("document").get_by_role("link", name="Inventory")
        if await inv_link.count() > 0:
            await inv_link.click()
            await page.wait_for_load_state("networkidle")
            await page.wait_for_timeout(300)
    except Exception:
        # fallback: a tab role named inventory
        try:
            inv_tab = page.get_by_role("tab", name=lambda n: n and "inventory" in n.lower())
            if await inv_tab.count() > 0:
                await inv_tab.click()
                await page.wait_for_timeout(300)
        except Exception:
            pass

    # Set Quantity = 50
    try:
        qty_tb = page.get_by_role("textbox", name=lambda n: n and ("qty" in n.lower() or "quantity" in n.lower()))
        if await qty_tb.count() > 0:
            await qty_tb.fill("50")
    except Exception:
        pass

    # Set Stock Availability -> In Stock (combobox/select)
    try:
        stock_cb = page.get_by_role("combobox", name=lambda n: n and ("stock" in n.lower() or "availability" in n.lower()))
        if await stock_cb.count() > 0:
            await stock_cb.select_option("In Stock")
    except Exception:
        pass

    # 4) Set Size -> 38 (combobox) if present
    try:
        size_cb = page.get_by_role("combobox", name=lambda n: n and "size" in n.lower())
        if await size_cb.count() > 0:
            await size_cb.select_option("38")
    except Exception:
        pass

    # 5) Set Color -> Yellow (combobox) if present; try a couple of label case variants
    try:
        color_cb = page.get_by_role("combobox", name=lambda n: n and "color" in n.lower())
        if await color_cb.count() > 0:
            for opt in ["Yellow", "yellow"]:
                try:
                    await color_cb.select_option(opt)
                    break
                except Exception:
                    continue
    except Exception:
        pass

    # 6) Final action: click Save (scope under document). This will navigate away so it must be last.
    # Use the explicit document -> button path per guidance
    save_clicked = False
    try:
        doc = page.get_by_role("document")
        if await doc.count() > 0:
            save_btn = doc.get_by_role("button", name=lambda n: n and n.strip().lower() == "save")
            if await save_btn.count() > 0:
                await save_btn.click()
                save_clicked = True
    except Exception:
        pass

    if not save_clicked:
        # fallback to any Save button on page
        try:
            any_save = page.get_by_role("button", name=lambda n: n and n.strip().lower() == "save")
            if await any_save.count() > 0:
                await any_save.click()
                save_clicked = True
        except Exception:
            pass

    if not save_clicked:
        raise RuntimeError("Unable to find Save button to complete product creation")

